-- Global physical test types and reference norms (WP10). Repeatable: Flyway re-runs this file when its checksum changes.
-- Generated from the tables documented in docs/domain/norms.md; ids are uuid5 of the natural key so upserts are stable.
--
-- SOURCING (WP27, WP62; see docs/domain/norms.md for every table, population and band mapping): reference_pending = false
-- for (1) COOPER_12MIN ages 13-19 (Cooper age/sex table as reproduced in secondary sources) and 8-12 (Balague et al. 1982,
-- Tabla I, Barcelona schoolchildren), (2) BEEP_TEST ages 8-18 (Ortega et al. 2023, FitBack European reference values,
-- Table 1), (3) SIT_AND_REACH ages 9-17 (Catley & Tomkinson 2013, Table 10), (4) SPRINT_20M ages 8-17 (Cossio-Bolanos et
-- al. 2026, centiles computed from the published LMS), (5) AGILITY_T_TEST and VERTICAL_JUMP ages 14-15 (Mascherini et al.
-- 2022, centiles interpolated between the published ones), (6) AGILITY_T_TEST ages 12-13 (Lesinski et al. 2020, Table 3,
-- elite young athletes), (7) VERTICAL_JUMP ages 12-13 and 16, boys 17 (Leone et al. 2025, Table 5, centiles computed from
-- the published LMS). Bands are cut at P20/P40/P60/P80. Everything else is a PLACEHOLDER (reference_pending = true, source
-- says "placeholder"): AGILITY_T_TEST and VERTICAL_JUMP 8-11 (synthetic monotone bands), AGILITY_T_TEST 16-18 (age 15
-- repeated), VERTICAL_JUMP girls 17-18 (girls 16 repeated) and boys 18 (boys 17 repeated), SIT_AND_REACH 8 and 18 and
-- SPRINT_20M 18 (the nearest cited age repeated).
-- Tenants never change these rows (RLS); they override them with their own norms (docs/domain/norms.md).
--
-- The app and migrator roles are subject to FORCEd row level security, and global rows (owner_tenant_id null) can
-- only be written with the table owner exempted, so FORCE is lifted for the duration of this transaction (DDL is
-- transactional: a failure leaves FORCE in place) and restored before it commits.
alter table athlete.physical_test_type no force row level security;
alter table athlete.physical_test_norm no force row level security;

on conflict (id) do update set code = excluded.code, name = excluded.name, unit = excluded.unit,
  higher_is_better = excluded.higher_is_better, description = excluded.description;

delete from athlete.physical_test_norm where owner_tenant_id is null and test_type_id in (select id from athlete.physical_test_type where owner_tenant_id is null and code in ('COOPER_12MIN', 'SPRINT_20M', 'VERTICAL_JUMP', 'AGILITY_T_TEST', 'SIT_AND_REACH', 'BEEP_TEST'));


alter table athlete.physical_test_type force row level security;
alter table athlete.physical_test_norm force row level security;
